SELECT id,name,city,country,address,open_time,adult_ticket_price,child_ticket_price, longitude,latitude,phone,description,stars,rating,tags,ai.image AS mainImage FROM attraction LEFT JOIN attraction_image AS ai ON ai.attraction_id = id AND ai.sort_order = 1
(name LIKE CONCAT('%', #{keyword}, '%') OR city LIKE CONCAT('%', #{keyword}, '%') OR country LIKE CONCAT('%', #{keyword}, '%') OR address LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND city = #{city}
AND (
FIND_IN_SET(#{tag}, tags) > 0
)
AND stars = #{stars}
ORDER BY rating DESC, id DESC
LIMIT #{offset}, #{size}

SELECT id,name,city,address,open_time,adult_ticket_price AS price,stars,rating,tags,ai.image AS image
FROM attraction LEFT JOIN attraction_image AS ai ON  ai.attraction_id = id AND ai.sort_order = 1

    AND city = #{city}

SELECT id,name,city,address,description,open_time,adult_ticket_price AS price,rating,tags,ai.image AS image
FROM attraction LEFT JOIN attraction_image AS ai ON  ai.attraction_id = id AND ai.sort_order = 1
WHERE id = #{id}
